import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CjAa9jTu.js";const m=JSON.parse('{"title":"Comunicación I²C","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/33_i2c.md","filePath":"py32f003-getting-started/33_i2c.md"}'),r={name:"py32f003-getting-started/33_i2c.md"};function t(c,e,s,l,d,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="comunicacion-i2c" tabindex="-1">Comunicación I²C <a class="header-anchor" href="#comunicacion-i2c" aria-label="Permalink to &quot;Comunicación I²C&quot;">​</a></h1><h2 id="concepto" tabindex="-1">Concepto <a class="header-anchor" href="#concepto" aria-label="Permalink to &quot;Concepto&quot;">​</a></h2><p>I²C utiliza dos señales: <strong>SDA</strong> para los datos y <strong>SCL</strong> para el reloj. El controlador inicia la comunicación con la dirección de un dispositivo; éste confirma su recepción con un acuse o ACK. Las líneas requieren resistencias de pull-up al nivel lógico del bus.</p><h2 id="conexiones-en-devlab-py32f003l24d6tr" tabindex="-1">Conexiones en DevLab PY32F003L24D6TR <a class="header-anchor" href="#conexiones-en-devlab-py32f003l24d6tr" aria-label="Permalink to &quot;Conexiones en DevLab PY32F003L24D6TR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Función I²C</th><th>Señal del microcontrolador</th><th>Conexión física compartida</th></tr></thead><tbody><tr><td>SDA</td><td>PA10</td><td>PA13 / SWDIO</td></tr><tr><td>SCL</td><td>PB6</td><td>PA14 / SWCLK</td></tr></tbody></table><p>El <a href="./03_pinout">pinout</a> y el <a href="/unit_devlab_cortex_m_examples/py32f003/esquematico.pdf">esquemático</a> muestran que esas señales comparten conexiones en esta variante DFN8. Dos conectores no significan que SWD e I²C puedan utilizarse al mismo tiempo.</p><h2 id="preparar-una-practica-posterior" tabindex="-1">Preparar una práctica posterior <a class="header-anchor" href="#preparar-una-practica-posterior" aria-label="Permalink to &quot;Preparar una práctica posterior&quot;">​</a></h2><ol><li>Compila y programa el firmware con los sensores desconectados.</li><li>Incluye un procedimiento probado para recuperar acceso SWD antes de reutilizar las líneas.</li><li>Desconecta la alimentación y el programador antes de conectar el periférico.</li><li>Verifica SDA, SCL, GND, alimentación y resistencias de pull-up del conjunto.</li><li>Ejecuta la prueba y registra dirección, respuesta y condiciones de alimentación.</li></ol><div class="info custom-block"><p class="custom-block-title">Alcance de los ejemplos iniciales</p><p>Las prácticas incluidas usan GPIO, UART y ADC y mantienen disponibles las líneas SWD. La combinación I²C/SWD requiere validación del montaje y del firmware por el instructor antes de incorporarla al taller.</p></div><h2 id="particularidades-del-paquete-arduino" tabindex="-1">Particularidades del paquete Arduino <a class="header-anchor" href="#particularidades-del-paquete-arduino" aria-label="Permalink to &quot;Particularidades del paquete Arduino&quot;">​</a></h2><p>El paquete 0.1.7 incluye <code>Wire</code> y permite seleccionar SDA y SCL antes de inicializar el bus. Sus valores genéricos por defecto son PF0 y PF1, que no se encuentran expuestos en esta placa. Una llamada aislada a <code>Wire.begin()</code> no basta para documentar un montaje con PA10/PB6.</p><p>Para un banco de pruebas, empieza por una dirección conocida y una transacción pequeña. Un ACK confirma presencia y comunicación básica; la lectura válida de un sensor exige revisar también su protocolo y datos.</p>',12)])])}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
